css
/* ? BLACK POLKADOT YOUTUBE THEME ? /

:root {
  --bg: #080808;
  --surface: #151515;
  --surface-hover: #242424;
  --text: #ffffff;
  --muted: #b5b5b5;
  --accent: #ffb6d5;
  --border: #353535;
}

/ Main background with polka dots /
html,
body,
ytd-app {
  background-color: var(--bg) !important;
  background-image: radial-gradient(
    circle,
    rgba(255, 255, 255, 0.65) 1.2px,
    transparent 1.6px
  ) !important;
  background-size: 32px 32px !important;
  color: var(--text) !important;
}

/ Main content panels /
#page-manager,
#contents,
ytd-browse,
ytd-search,
ytd-watch-flexy {
  background-color: rgba(8, 8, 8, 0.94) !important;
  color: var(--text) !important;
}

/ Header / navigation bar /
#masthead-container,
ytd-masthead {
  background: #090909 !important;
  border-bottom: 1px solid var(--border) !important;
}

/ Sidebar /
#guide-content,
ytd-mini-guide-renderer {
  background-color: #0b0b0b !important;
}

ytd-guide-entry-renderer,
ytd-mini-guide-entry-renderer {
  border-radius: 12px !important;
  margin: 3px 8px !important;
}

ytd-guide-entry-renderer:hover {
  background: var(--surface-hover) !important;
}

/ Video cards /
ytd-rich-item-renderer,
ytd-compact-video-renderer,
ytd-video-renderer {
  border-radius: 16px !important;
  overflow: hidden !important;
}

/ Rounded thumbnails /
ytd-thumbnail,
ytd-thumbnail img,
#thumbnail {
  border-radius: 14px !important;
  overflow: hidden !important;
}

/ Video titles /
#video-title,
ytd-video-renderer #video-title {
  color: var(--text) !important;
  font-weight: 600 !important;
}

/ Channel names and metadata /
#channel-name,
#metadata-line,
.ytd-video-meta-block {
  color: var(--muted) !important;
}

/ Search bar /
#container.ytd-searchbox {
  background: #171717 !important;
  border: 1px solid var(--border) !important;
  border-radius: 24px !important;
}

#search-input input {
  color: var(--text) !important;
}

/ Buttons and category chips /
yt-chip-cloud-chip-renderer,
ytd-feed-filter-chip-bar-renderer button {
  border-radius: 20px !important;
}

yt-chip-cloud-chip-renderer[chip-style="STYLE_HOME_FILTER"] {
  background: var(--surface) !important;
  color: var(--text) !important;
}

/ Pink accents for interactive elements /
a:hover,
#video-title:hover,
yt-formatted-string a:hover {
  color: var(--accent) !important;
}

/ Subscribe button /
ytd-subscribe-button-renderer button,
yt-button-shape button {
  border-radius: 22px !important;
}

/ Scrollbar /
::-webkit-scrollbar {
  width: 9px;
}

::-webkit-scrollbar-track {
  background: #080808;
}

::-webkit-scrollbar-thumb {
  background: #555;
  border-radius: 12px;
  border: 2px solid #080808;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--accent);
}

/ Selection highlight */
::selection {
  background: var(--accent);
  color: #080808;
}
